mapper.select:
select id, key_name as keyName, key_type as keyType, key_desc as keyDesc, create_time as createTime, update_time as updateTime, api_key as apiKey, dify_app_type as difyAppType, is_default as isDefault from dify_api_key_config
key_type = #{keyType}
and dify_app_type = #{difyAppType}
and key_name like CONCAT('%',#{keyName},'%')
and api_key like CONCAT('%',#{apiKey},'%')
order by is_default desc, update_time desc
